  ('english', 'ป.6', '3', 'ภาษากับความสัมพันธ์กับกลุ่มสาระการเรียนรู้อื่น', 'ต 3.1', 'ต 3.1 ป.6/1', 'ค้นคว้า รวบรวม คำศัพท์ที่เกี่ยวข้อง กับกลุ่มสาระ การเรียนรู้อื่นจากแหล่งการเรียนรู้ และนำเสนอด้วยการพูด/การเขียน 17', 'ปลายทาง', 107),
  ('english', 'ป.6', '4', 'ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ต 4.1', 'ต 4.1 ป.6/1', 'ใช้ภาษาสื่อสาร ในสถานการณ์ต่าง ๆ ที่เกิดขึ้น ในห้องเรียนและสถานศึกษา', 'ปลายทาง', 108),
  ('english', 'ป.6', '3', 'ภาษากับความสัมพันธ์กับกลุ่มสาระการเรียนรู้อื่น', 'ต 4.2', 'ต 4.2 ป.6/1', 'ใช้ภาษาต่างประเทศในการสืบค้นและรวบรวม ข้อมูลต่าง ๆ', 'ระหว่างทาง', 109)
